(function(){'use strict';var SUPPORTED_LANGS=['fr','en','nl','de','it'];var DEFAULT_LANG='fr';var STORAGE_KEY='chalet_lang_pref';function getCurrentLang(){var path=window.location.pathname;for(var i=0;i<SUPPORTED_LANGS.length;i++){if(path.indexOf('/'+SUPPORTED_LANGS[i]+'/')===0){return SUPPORTED_LANGS[i];}}
return DEFAULT_LANG;}
function detectBrowserLang(){var navLang=(navigator.language||navigator.userLanguage||'').toLowerCase();var primary=navLang.split('-')[0];if(SUPPORTED_LANGS.indexOf(primary)!==-1){return primary;}
return DEFAULT_LANG;}
function getLangUrl(lang){if(lang===DEFAULT_LANG){return'/';}
return'/'+lang+'/';}
function autoRedirect(){if(/bot|crawl|spider|slurp|facebookexternalhit|WhatsApp|ChatGPT|Anthropic|Claude|Perplexity/i.test(navigator.userAgent)){return;}
if(localStorage.getItem(STORAGE_KEY)){return;}
var currentLang=getCurrentLang();var browserLang=detectBrowserLang();localStorage.setItem(STORAGE_KEY,currentLang);var path=window.location.pathname;if(currentLang!==DEFAULT_LANG){return;}
if(browserLang!==currentLang){localStorage.setItem(STORAGE_KEY,browserLang);window.location.href=getLangUrl(browserLang);}}
function highlightActiveLang(){var currentLang=getCurrentLang();var items=document.querySelectorAll('#langSwitcher .dropdown-item');for(var i=0;i<items.length;i++){var itemLang=items[i].getAttribute('data-lang');if(itemLang===currentLang){items[i].classList.add('active');}else{items[i].classList.remove('active');}}}
function setupSwitcher(){var items=document.querySelectorAll('#langSwitcher .dropdown-item');for(var i=0;i<items.length;i++){items[i].addEventListener('click',function(e){var lang=this.getAttribute('data-lang');localStorage.setItem(STORAGE_KEY,lang);});}}
document.addEventListener('DOMContentLoaded',function(){highlightActiveLang();setupSwitcher();autoRedirect();});})();